import useIncentiveStore from '@/store/incentive'
import { useSdk } from '@cetus/sdk-factory'
import { camelCaseObject } from '@cetus/utils'
import useGetDlmmPools from '../pool/useGetDlmmPools'

function useGetIncentivePoolInfo() {
  const dlmmSdk = useSdk('dlmm')
  const { getDlmmPools } = useGetDlmmPools()
  const { setIncentiveApiPoolInfo, setIncentiveContractPoolInfo } = useIncentiveStore()

  const getIncentivePoolInfo = async (poolAddress: string) => {
    if (!poolAddress) return
    let poolInfo: any = null
    try {
      poolInfo = await getDlmmPools({ pools: [poolAddress], display_all_pools: true })
    } catch (error) {
      console.error('getDlmmContractPoolInfo error:', error)
    } finally {
    }

    console.log('🚀 ~ getPosPoolPoolData ~ data:', poolAddress, poolInfo)
    if (poolInfo) {
      setIncentiveApiPoolInfo(poolInfo?.list[0])
    }
  }

  const getIncentiveContractPoolInfo = async (poolAddress: string) => {
    let poolInfo: any = null
    if (dlmmSdk) {
      try {
        const res = await dlmmSdk!.Pool.getPool(poolAddress)
        poolInfo = { ...res, ...camelCaseObject(res), poolAddress: res?.id }
        console.log('🚀 ~ getIncentiveContractPoolInfo ~ poolInfo:', poolInfo)
        setIncentiveContractPoolInfo(poolInfo)
      } catch (error) {
        console.error('getDlmmContractPoolInfo error:', error)
      } finally {
      }
    }
    console.log(poolInfo, 'get-poolInfo')
    if (poolInfo) {
      setIncentiveContractPoolInfo(poolInfo as any)
    }
  }

  return { getIncentivePoolInfo, getIncentiveContractPoolInfo }
}
export default useGetIncentivePoolInfo
