import { generateRewardSchedule } from 'dd_dlmm_sdk'

export const REWARD_PERIOD = 7 * 24 * 60 * 60 * 1000
export const REWARD_PERIOD_START_AT = 1747627200
interface timeOptionsParams {
  maxIntervals: number
  baseTime?: number
  timeInterval?: number
}
function useGetIncentiveTimeOptions() {
  const getIncentiveTimeOptions = async ({ maxIntervals, baseTime = REWARD_PERIOD_START_AT, timeInterval = REWARD_PERIOD }: timeOptionsParams) => {
    try {
      const res = await generateRewardSchedule(baseTime, maxIntervals, timeInterval)
      console.log('🚀 ~ getIncentiveTimeOptions ~ res:', res)
      return res
    } catch (error) {
      console.error('getDlmmContractPoolInfo error:', error)
    } finally {
    }
  }

  return { getIncentiveTimeOptions }
}
export default useGetIncentiveTimeOptions
